{
  "root": "main_stack",
  "state": {
    "itinerary": [
      {
        "dayDate": "Friday, September 20",
        "icon": "../assets/r_000472_01_1_house.svg",
        "time": "09:30 AM - 12:00 PM",
        "activity": "Arrival & Welcome Reception",
        "details": "Icebreaker: 'Two Truths and a Lie' to encourage personal sharing."
      },
      {
        "dayDate": "Friday, September 20",
        "icon": "../assets/r_000472_01_1_house.svg",
        "time": "12:00 PM - 01:00 PM",
        "activity": "Casual Buffet Lunch",
        "details": "Opportunity for informal networking."
      },
      {
        "dayDate": "Friday, September 20",
        "icon": "../assets/r_000472_01_1_house.svg",
        "time": "01:00 PM - 05:00 PM",
        "activity": "Outdoor Collaboration Challenge: 'Bridge Build'",
        "details": "Teams work together to design and construct a small bridge using limited materials, testing planning and execution."
      },
      {
        "dayDate": "Friday, September 20",
        "icon": "../assets/r_000472_01_1_house.svg",
        "time": "06:30 PM - 07:30 PM",
        "activity": "Group Dinner",
        "details": "Enjoy local cuisine, fostering a shared experience."
      },
      {
        "dayDate": "Friday, September 20",
        "icon": "../assets/r_000472_01_1_house.svg",
        "time": "07:30 PM - 09:00 PM",
        "activity": "Campfire & Storytelling",
        "details": "Relaxed session to share team successes, funny anecdotes, and personal aspirations."
      },
      {
        "dayDate": "Saturday, September 21",
        "icon": "../assets/r_000473_01_5_puzzle.svg",
        "time": "09:00 AM - 12:00 PM",
        "activity": "'Escape the Room' Challenge",
        "details": "Teams solve a series of interconnected puzzles under time pressure, emphasizing logical thinking and collaborative problem-solving."
      },
      {
        "dayDate": "Saturday, September 21",
        "icon": "../assets/r_000473_01_5_puzzle.svg",
        "time": "12:00 PM - 01:00 PM",
        "activity": "Picnic Lunch (weather permitting)",
        "details": "A refreshing break in the rural environment."
      },
      {
        "dayDate": "Saturday, September 21",
        "icon": "../assets/r_000473_01_5_puzzle.svg",
        "time": "01:00 PM - 05:00 PM",
        "activity": "Communication & Trust Building: 'Blindfolded Obstacle Course'",
        "details": "One team member is blindfolded and guided by verbal instructions from their teammates through an obstacle course."
      },
      {
        "dayDate": "Saturday, September 21",
        "icon": "../assets/r_000473_01_5_puzzle.svg",
        "time": "06:30 PM - 07:30 PM",
        "activity": "Themed Dinner Night",
        "details": "E.g., BBQ or International Cuisine, promoting cultural sharing and enjoyment."
      },
      {
        "dayDate": "Saturday, September 21",
        "icon": "../assets/r_000473_01_5_puzzle.svg",
        "time": "07:30 PM - 09:00 PM",
        "activity": "Team Talent Show / Karaoke",
        "details": "A light-hearted social event to showcase hidden talents and build camaraderie."
      },
      {
        "dayDate": "Sunday, September 22",
        "icon": "../assets/r_000472_01_3_arrow-repeat.svg",
        "time": "09:00 AM - 12:00 PM",
        "activity": "'Vision Board' Collaboration",
        "details": "Teams create a collective vision board for upcoming projects or team goals, translating discussions into visual action plans."
      },
      {
        "dayDate": "Sunday, September 22",
        "icon": "../assets/r_000472_01_3_arrow-repeat.svg",
        "time": "12:00 PM - 01:00 PM",
        "activity": "Farewell Lunch",
        "details": "A final meal together, celebrating achievements and connections made."
      },
      {
        "dayDate": "Sunday, September 22",
        "icon": "../assets/r_000472_01_3_arrow-repeat.svg",
        "time": "01:00 PM - 02:00 PM",
        "activity": "Retreat Wrap-up & Departure",
        "details": "Share key takeaways, feedback, and final remarks before departure."
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "overview_card",
        "itinerary_title",
        "itinerary_table",
        "quick_actions_title",
        "quick_actions_stack",
        "sources_title",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Corporate Team Retreat: Cultivating Collaboration in Nature",
        "variant": "h1"
      },
      "children": []
    },
    "overview_card": {
      "type": "Card",
      "props": {},
      "children": [
        "overview_header_stack",
        "overview_text_intro",
        "overview_text_principles"
      ]
    },
    "overview_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "overview_icon",
        "overview_heading"
      ]
    },
    "overview_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000473_01_1_people.svg"
      },
      "children": []
    },
    "overview_heading": {
      "type": "Text",
      "props": {
        "text": "Retreat Overview & Guiding Principles",
        "variant": "h2"
      },
      "children": []
    },
    "overview_text_intro": {
      "type": "Text",
      "props": {
        "text": "This 3-day retreat is designed for 20 employees in a rural setting, focusing on enhancing communication, problem-solving, and team cohesion. The schedule balances structured team-building activities with opportunities for relaxation and informal interaction, leveraging the natural environment."
      },
      "children": []
    },
    "overview_text_principles": {
      "type": "Text",
      "props": {
        "text": "This itinerary for September 20-22, 2024, aims to strengthen team bonds and equip employees with improved collaborative skills. Activities are designed to be engaging, inclusive, and foster a positive, supportive team environment."
      },
      "children": []
    },
    "itinerary_title": {
      "type": "Text",
      "props": {
        "text": "Day-by-Day Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayDate",
        "highlightColumns": ["activity"],
        "columns": [
          {
            "key": "dayDate",
            "label": "Day"
          },
          {
            "key": "icon",
            "label": "Icon"
          },
          {
            "key": "time",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          },
          {
            "key": "details",
            "label": "Details"
          }
        ]
      },
      "children": []
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_find_venues",
        "button_activity_guide"
      ]
    },
    "button_find_venues": {
      "type": "Button",
      "props": {
        "label": "Find Venues"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.peerspace.com/"
          }
        }
      },
      "children": []
    },
    "button_activity_guide": {
      "type": "Button",
      "props": {
        "label": "Activity Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.teambuilding.com/blog/team-building-activities"
          }
        }
      },
      "children": []
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_source_teambuilding",
        "button_source_eventplanning"
      ]
    },
    "button_source_teambuilding": {
      "type": "Button",
      "props": {
        "label": "Team Building Resources"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/teambuilding"
          }
        }
      },
      "children": []
    },
    "button_source_eventplanning": {
      "type": "Button",
      "props": {
        "label": "Event Planning Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.example.com/eventplanning"
          }
        }
      },
      "children": []
    }
  }
}
